10:     /// Navigate the underlying WebView2 to an inline HTML document and block
11:     /// until `NavigationCompleted` fires (or the configured timeout elapses).
12:     pub fn navigate_to_string(&self, html: &str, timeout: Duration) -> Result<(), WebSurfaceError> {
13:         let (tx, rx) = mpsc::channel::<()>();
14:         let mut navigation_token = 0;
15:         let handler = NavigationCompletedEventHandler::create(Box::new(move |_sender, _args| {
16:             let _ = tx.send(());
17:             Ok(())
18:         }));
19: 
20:         unsafe {
21:             self.webview
22:                 .add_NavigationCompleted(&handler, &mut navigation_token)
23:                 .map_err(platform("add_NavigationCompleted"))?;
24:             let html = CoTaskMemPWSTR::from(html);
25:             self.webview
26:                 .NavigateToString(*html.as_ref().as_pcwstr())
27:                 .map_err(platform("NavigateToString"))?;
28:         }
29: 
30:         let result = pump_until(timeout, &rx);
31: 
32:         unsafe {
33:             let _ = self
34:                 .webview
35:                 .remove_NavigationCompleted(navigation_token)
36:                 .map_err(webview2_com::Error::WindowsError);
37:         }
38: 
39:         result.map_err(|()| {
40:             WebSurfaceError::Platform(format!(
41:                 "WebView2 navigation did not complete within {timeout:?}"
42:             ))
43:         })?;
44: 
45:         self.wait_for_render_tick()
46:     }
