215:         &mut self,
216:         timeout: Duration,
217:     ) -> Result<WebView2CompositionFrame, WebSurfaceError> {
218:         if self.capture_state.is_none() {
219:             self.start_capture()?;
220:         }
221:         let needs_nudge = self
222:             .capture_state
223:             .as_ref()
224:             .map(|state| !state.first_frame_emitted)
225:             .unwrap_or(true);
