228:         }
229:         let deadline = Instant::now() + timeout;
230:         loop {
231:             let state = self
232:                 .capture_state
233:                 .as_mut()
234:                 .expect("capture state populated above");
235:             if !state.frame_ready() {
236:                 if Instant::now() < deadline {
237:                     pump_messages_for(Duration::from_millis(16));
238:                     continue;
239:                 }
240:                 return Err(WebSurfaceError::Platform(format!(
241:                     "WGC frame did not arrive within {timeout:?} for {}x{}",
242:                     self.size.width, self.size.height
243:                 )));
244:             }
245:             match state.take_latest_frame() {
246:                 Ok(frame) => match self.capture_frame_to_shared(frame)? {
247:                     Some(frame) => return Ok(frame),
248:                     None if Instant::now() < deadline => {
249:                         pump_messages_for(Duration::from_millis(16))
250:                     },
251:                     None => {
