258:                 Err(error) => {
259:                     return Err(WebSurfaceError::Platform(format!(
260:                         "TryGetNextFrame timed out after {timeout:?} for {}x{}: {error}",
261:                         self.size.width, self.size.height
262:                     )));
263:                 },

