283:             return Ok(None);
284:         }
285:         let surface = frame
286:             .Surface()
287:             .map_err(platform("Direct3D11CaptureFrame::Surface"))?;
288:         let access = surface
289:             .cast::<IDirect3DDxgiInterfaceAccess>()
290:             .map_err(platform(
