308:         let fence_value = self.capture_factory.copy_capture_into_existing_target(
309:             &dest.texture,
310:             WebView2D3D11CaptureFrame {
311:                 size: captured_size,
312:                 format: wgpu::TextureFormat::Bgra8Unorm,
313:                 generation: self.resource_epoch,
314:                 raw_d3d11_texture: raw_texture,
