441: const CAPTURE_POOL_BUFFERS: usize = 2;
442: 
443: /// A readiness notification coalesces all arrivals since the previous poll.
444: /// Drain at most the pool capacity so that a static page's final queued paint
445: /// is not stranded behind that coalesced notification. Close superseded frames
446: /// before converting the newest sample; arrivals during this bounded drain
447: /// retain their notification for the next poll.
448: fn newest_queued_capture_frame<T, E>(
449:     mut next: impl FnMut() -> Result<T, E>,
450:     mut close: impl FnMut(T),
451: ) -> Result<T, E> {
452:     let mut latest = next()?;
453:     for _ in 1..CAPTURE_POOL_BUFFERS {
454:         let Ok(frame) = next() else {
455:             break;
456:         };
457:         close(latest);
458:         latest = frame;
459:     }
460:     Ok(latest)

